<?php if ($entradas !== []): ?><section class="panel issued-tickets"><div class="panel-heading"><div><h2>Entradas emitidas</h2><p><?= count($entradas) ?> boleto(s)</p></div></div><div class="table-wrap"><table><thead><tr><th>Entrada</th><th>Evento</th><th>Función</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($entradas as $e): ?><tr><td><strong><?= esc($e['codigo']) ?></strong><small><?= esc($e['tipo_nombre']) ?></small></td><td><?= esc($e['evento_nombre']) ?></td><td><strong><?= esc(date('d/m/Y H:i', strtotime($e['fecha_inicio']))) ?></strong><small><?= esc($e['recinto'] . ', ' . $e['ciudad']) ?></small></td><td><span class="tag <?= esc($e['estado']) ?>"><?= esc(ucfirst($e['estado'])) ?></span></td><td><a class="secondary-button" target="_blank" href="<?= base_url('admin/ventas/entradas/' . $e['id'] . '/imprimir') ?>">Imprimir</a></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
